def expand_ranges(s: str) -> list[int]:
    if not s:
        return []

    def parse_range(part):
        start, end = part.split('-')
        if not start.isdigit() or not end.isdigit():
            raise ValueError(f"Invalid range part: {part}")

        start, end = int(start), int(end)
        if start > end:
            raise ValueError(f"Descending range detected: {part}")

        return list(range(start, end + 1))

    parts = s.split(',')
    expanded = []

    for part in parts:
        try:
            expanded.extend(parse_range(part))
        except ValueError as e:
            print(f"Skipping invalid range part: {part} - {e}")

    return sorted(expanded)

